contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newLimit) public payable {
        require(true);

        // read previous bet limit
        uint256 beforeLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call that may revert (onlyOwner modifier may cause revert)
        c.AdjustBetAmounts(newLimit); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after value
        uint256 afterLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        // General rule: either the call reverted and the limit is unchanged, or it succeeded and the limit equals newLimit
        assert((reverted && afterLimit == beforeLimit) || (!reverted && afterLimit == newLimit));
    }

    receive() external payable {}
}

