contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newLimit) internal {
        vm.assume(true);
        uint256 beforeLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeLimit = __r; } catch { return; }
        bool reverted;
        try c.AdjustBetAmounts(newLimit) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterLimit;
        try c.currentBetLimit() returns (uint256 __r) { afterLimit = __r; } catch { return; }
        assertTrue((reverted && afterLimit == beforeLimit) || (!reverted && afterLimit == newLimit));
    }

    function testFuzz_run(uint256 newLimit) public {
        _run(newLimit);
    }

    receive() external payable {}
}
